def is_palindrome(s):
    l, r = 0, len(s) - 1
    while l < r:
        while l < r and not s[l].isalnum():
            l += 1
        while l < r and not s[r].isalnum():
            r -= 1
        if s[l].lower() != s[r].lower():
            return False
        l, r = l + 1, r - 1
    return True

def two_sum(numbers, target):
    l, r = 0, len(numbers) - 1
    while l < r:
        total = numbers[l] + numbers[r]
        if total == target:
            return [l + 1, r + 1]      # 1-indexed
        if total < target:
            l += 1
        else:
            r -= 1
    return []

def three_sum(nums):
    nums.sort()
    res = []
    for i in range(len(nums) - 2):
        if nums[i] > 0:
            break
        if i > 0 and nums[i] == nums[i - 1]:
            continue                   # same fixed value → same triplets
        l, r = i + 1, len(nums) - 1
        while l < r:
            total = nums[i] + nums[l] + nums[r]
            if total < 0:
                l += 1
            elif total > 0:
                r -= 1
            else:
                res.append([nums[i], nums[l], nums[r]])
                l += 1
                while l < r and nums[l] == nums[l - 1]:
                    l += 1
                r -= 1
    return res

def max_area(height):
    l, r, best = 0, len(height) - 1, 0
    while l < r:
        best = max(best, (r - l) * min(height[l], height[r]))
        if height[l] < height[r]:
            l += 1                     # the shorter wall can never do better
        else:
            r -= 1
    return best

def has_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            return True
    return False

def is_happy(n):
    def f(x):
        return sum(int(d) ** 2 for d in str(x))

    slow, fast = f(n), f(f(n))
    while fast != 1 and slow != fast:
        slow, fast = f(slow), f(f(fast))
    return fast == 1

def find_duplicate(nums):
    slow = fast = 0                    # index i points to nums[i]
    while True:
        slow = nums[slow]
        fast = nums[nums[fast]]
        if slow == fast:
            break
    slow = 0                           # phase 2: meet at the cycle entry
    while slow != fast:
        slow, fast = nums[slow], nums[fast]
    return slow

def check_inclusion(s1, s2):
    k = len(s1)
    if k > len(s2):
        return False
    diff = [0] * 26                    # count(s1) - count(window)
    for c in s1:
        diff[ord(c) - 97] += 1
    for c in s2[:k]:
        diff[ord(c) - 97] -= 1
    matched = sum(d == 0 for d in diff)

    def update(i, delta):
        nonlocal matched
        if diff[i] == 0:
            matched -= 1
        diff[i] += delta
        if diff[i] == 0:
            matched += 1

    for r in range(k, len(s2)):
        if matched == 26:
            return True
        update(ord(s2[r]) - 97, -1)      # letter entering
        update(ord(s2[r - k]) - 97, +1)  # letter leaving
    return matched == 26

def length_of_longest_substring(s):
    last = {}                          # char → last index seen
    l = best = 0
    for r, c in enumerate(s):
        if c in last:
            l = max(l, last[c] + 1)    # never move l backwards
        last[c] = r
        best = max(best, r - l + 1)
    return best

def contains_nearby_duplicate(nums, k):
    last = {}                          # value → last index
    for i, x in enumerate(nums):
        if x in last and i - last[x] <= k:
            return True
        last[x] = i
    return False

def longest_consecutive(nums):
    values = set(nums)
    best = 0
    for x in values:
        if x - 1 not in values:        # x is a run head
            y = x
            while y + 1 in values:
                y += 1
            best = max(best, y - x + 1)
    return best

def max_sub_array(nums):
    cur = best = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x)          # extend, or restart at x
        best = max(best, cur)
    return best

def max_product(nums):
    cur_max = cur_min = best = nums[0]
    for x in nums[1:]:
        if x < 0:
            cur_max, cur_min = cur_min, cur_max   # a negative flips the roles
        cur_max = max(x, cur_max * x)
        cur_min = min(x, cur_min * x)
        best = max(best, cur_max)
    return best

def remove_element(nums, val):
    k = 0                              # write pointer
    for x in nums:
        if x != val:
            nums[k] = x
