    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]
            low += 1
            mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:                          # 2: swap to the back, re-check mid
            nums[mid], nums[high] = nums[high], nums[mid]
            high -= 1

