def merge(intervals):
    intervals.sort(key=lambda iv: iv[0])
    merged = []
    for start, end in intervals:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)   # extend the tail
        else:
            merged.append([start, end])
    return merged

def missing_number(nums):
    acc = len(nums)                    # the index n has no slot
    for i, x in enumerate(nums):
        acc ^= i ^ x                   # pairs cancel, the missing one remains
    return acc

def first_missing_positive(nums):
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            j = nums[i] - 1            # value v belongs in slot v-1
            nums[i], nums[j] = nums[j], nums[i]
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    return n + 1

def can_attend_meetings(intervals):
    intervals.sort(key=lambda iv: iv[0])
    for i in range(1, len(intervals)):
        if intervals[i][0] < intervals[i - 1][1]:
            return False
    return True

def erase_overlap_intervals(intervals):
    intervals.sort(key=lambda iv: iv[1])   # earliest end leaves the most room
    kept, prev_end = 0, float('-inf')
    for start, end in intervals:
        if start >= prev_end:
            kept += 1
            prev_end = end
    return len(intervals) - kept

