def find_maximized_capital(k, w, profits, capital):
    locked = list(zip(capital, profits))   # min-heap by capital
    heapq.heapify(locked)
    affordable = []                        # max-heap by profit (negated)
    for _ in range(k):
        while locked and locked[0][0] <= w:
            heapq.heappush(affordable, -heapq.heappop(locked)[1])
        if not affordable:
            break
        w -= heapq.heappop(affordable)
    return w

