def least_interval(tasks, n):
    counts = Counter(tasks).values()
    f = max(counts)                             # max frequency
    c = sum(1 for x in counts if x == f)        # tasks tied at f
    return max(len(tasks), (f - 1) * (n + 1) + c)

def merge_two_lists(l1, l2):
    dummy = tail = ListNode()
    while l1 and l2:
        if l1.val <= l2.val:
            tail.next, l1 = l1, l1.next
        else:
            tail.next, l2 = l2, l2.next
        tail = tail.next
    tail.next = l1 or l2               # splice the leftover run
    return dummy.next

def merge_k_lists(lists):
    def merge_two(a, b):
        dummy = tail = ListNode()
        while a and b:
            if a.val <= b.val:
                tail.next, a = a, a.next
            else:
                tail.next, b = b, b.next
            tail = tail.next
        tail.next = a or b
        return dummy.next

    if not lists:
        return None
    interval = 1
    while interval < len(lists):       # rounds: merge pairs at doubling gaps
        for i in range(0, len(lists) - interval, interval * 2):
            lists[i] = merge_two(lists[i], lists[i + interval])
        interval *= 2
    return lists[0]

def daily_temperatures(temps):
    res = [0] * len(temps)
    stack = []                         # indices, temperatures decreasing
    for i, t in enumerate(temps):
        while stack and temps[stack[-1]] < t:
            j = stack.pop()            # i is j's next warmer day
            res[j] = i - j
        stack.append(i)
    return res

def car_fleet(target, position, speed):
    stack = []                         # arrival time of each fleet
    for p, s in sorted(zip(position, speed), reverse=True):
        time = (target - p) / s
        if not stack or time > stack[-1]:
            stack.append(time)         # slower than the fleet ahead: new fleet
    return len(stack)

