def max_sliding_window(nums, k):
    dq, res = deque(), []              # indices, values decreasing front → back
    for i, x in enumerate(nums):
        while dq and nums[dq[-1]] <= x:
            dq.pop()                   # can never be a max again
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()               # slid out of the window
        if i >= k - 1:
            res.append(nums[dq[0]])
    return res

def is_valid(s):
    closer = {'(': ')', '[': ']', '{': '}'}
    stack = []                         # expected closing brackets
    for c in s:
        if c in closer:
            stack.append(closer[c])
        elif not stack or stack.pop() != c:
            return False
    return not stack

class MinStack:
    def __init__(self):
        self.stack = []                # (value, min so far)

    def push(self, val):
        low = min(val, self.stack[-1][1]) if self.stack else val
        self.stack.append((val, low))

    def pop(self):
        self.stack.pop()

    def top(self):
        return self.stack[-1][0]

    def getMin(self):
        return self.stack[-1][1]

def eval_rpn(tokens):
    stack = []
    for t in tokens:
        if t in {'+', '-', '*', '/'}:
            b, a = stack.pop(), stack.pop()    # right operand pops first
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:
                stack.append(int(a / b))       # truncate toward zero
        else:
            stack.append(int(t))
    return stack[0]

def calculate(s):
    res, num, sign = 0, 0, 1
    stack = []                         # (res before '(', sign before '(')
    for c in s:
        if c.isdigit():
            num = num * 10 + int(c)
        elif c in '+-':
            res += sign * num
            num, sign = 0, (1 if c == '+' else -1)
        elif c == '(':
            stack.append(res)
            stack.append(sign)
            res, sign = 0, 1
        elif c == ')':
            res += sign * num
            num = 0
            res *= stack.pop()         # sign before the paren
            res += stack.pop()         # result before the paren
    return res + sign * num

def remove_nth_from_end(head, n):
    dummy = ListNode(0, head)
    slow = fast = dummy
    for _ in range(n + 1):
        fast = fast.next               # gap of n nodes between slow and fast
    while fast:
        slow, fast = slow.next, fast.next
    slow.next = slow.next.next         # slow sits just before the target
    return dummy.next

