def average_of_levels(root):
    res, queue = [], deque([root])
    while queue:
        size, total = len(queue), 0    # snapshot: this level only
        for _ in range(size):
            node = queue.popleft()
            total += node.val
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        res.append(total / size)
    return res

