from collections import deque

def zigzag_level_order(root):
    if not root:
        return []
    res, queue, left_to_right = [], deque([root]), True
    while queue:
        level = deque()
        for _ in range(len(queue)):
            node = queue.popleft()
            if left_to_right:
                level.append(node.val)
            else:
                level.appendleft(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        res.append(list(level))
        left_to_right = not left_to_right
    return res

def max_depth(root):
    if not root:
        return 0
    return 1 + max(max_depth(root.left), max_depth(root.right))

def is_same_tree(p, q):
    if not p or not q:
        return p is q                  # both empty, or one is missing
    return (p.val == q.val
            and is_same_tree(p.left, q.left)
            and is_same_tree(p.right, q.right))

def invert_tree(root):
    if root:
        root.left, root.right = invert_tree(root.right), invert_tree(root.left)
    return root

def diameter_of_binary_tree(root):
    best = 0

    def height(node):
        nonlocal best
        if not node:
            return 0
        l, r = height(node.left), height(node.right)
        best = max(best, l + r)        # longest path through this node (edges)
        return 1 + max(l, r)

    height(root)
    return best

def is_balanced(root):
    def height(node):                  # -1 = unbalanced below
        if not node:
            return 0
        l = height(node.left)
        if l == -1:
            return -1
        r = height(node.right)
        if r == -1 or abs(l - r) > 1:
            return -1
        return 1 + max(l, r)

    return height(root) != -1

def is_subtree(root, sub_root):
    def serialize(node, out):
        if not node:
            out.append('#')            # explicit null markers
            return
        out.append(f'^{node.val}')     # '^' stops "2" matching inside "12"
        serialize(node.left, out)
        serialize(node.right, out)

    a, b = [], []
    serialize(root, a)
    serialize(sub_root, b)
    return ','.join(b) in ','.join(a)

class Codec:
    def serialize(self, root):
        out = []

        def dfs(node):                 # preorder, '#' for null
            if not node:
                out.append('#')
                return
            out.append(str(node.val))
            dfs(node.left)
            dfs(node.right)

        dfs(root)
        return ','.join(out)

