        node = self.root
        for c in word:
            i = ord(c) - 97
            if not node.children[i]:
                node.children[i] = TrieNode()
            node = node.children[i]
        node.is_end = True

    def _walk(self, s):
        node = self.root
        for c in s:
            node = node.children[ord(c) - 97]
            if not node:
                return None
        return node

    def search(self, word):
        node = self._walk(word)
        return bool(node and node.is_end)

    def startsWith(self, prefix):
        return self._walk(prefix) is not None

class WordDictionary:
    def __init__(self):
        self.root = {}                 # char → child dict; '$' marks a word end

    def addWord(self, word):
        node = self.root
        for c in word:
            node = node.setdefault(c, {})
        node['$'] = True

    def search(self, word):
        def dfs(node, i):
            if i == len(word):
                return '$' in node
            c = word[i]
            if c == '.':               # fork into every child
                return any(dfs(child, i + 1) for key, child in node.items() if key != '$')
            return c in node and dfs(node[c], i + 1)

        return dfs(self.root, 0)

def find_words(board, words):
    root = {}                          # trie of every word; '$' holds the word
    for w in words:
        node = root
        for c in w:
            node = node.setdefault(c, {})
        node['$'] = w

    m, n = len(board), len(board[0])
    found = []

    def dfs(r, c, parent):
        ch = board[r][c]
        node = parent[ch]
        if '$' in node:
            found.append(node.pop('$'))    # pop: report each word once
        board[r][c] = '#'
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < m and 0 <= nc < n and board[nr][nc] in node:
                dfs(nr, nc, node)
        board[r][c] = ch
        if not node:
            parent.pop(ch)                 # prune exhausted branches

    for r in range(m):
        for c in range(n):
            if board[r][c] in root:
                dfs(r, c, root)
    return found

