def ladder_length(begin_word, end_word, word_list):
    if end_word not in word_list:
        return 0
    L = len(begin_word)
    buckets = defaultdict(list)        # "h*t" → ["hot", "hit", ...]
    for w in word_list:
        for i in range(L):
            buckets[w[:i] + '*' + w[i + 1:]].append(w)

    seen = {begin_word}
    queue = deque([(begin_word, 1)])
    while queue:
        word, steps = queue.popleft()
        for i in range(L):
            key = word[:i] + '*' + word[i + 1:]
            for nxt in buckets[key]:
                if nxt == end_word:
                    return steps + 1
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append((nxt, steps + 1))
            buckets[key] = []          # each bucket only needs expanding once
    return 0

def num_islands(grid):
    m, n = len(grid), len(grid[0])
    count = 0
    for r in range(m):
        for c in range(n):
            if grid[r][c] != '1':
                continue
            count += 1
            grid[r][c] = '0'           # sink on first contact
            stack = [(r, c)]           # explicit stack: no recursion limit
            while stack:
                i, j = stack.pop()
                for ni, nj in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                    if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == '1':
                        grid[ni][nj] = '0'
                        stack.append((ni, nj))
    return count

