                continue
            grid[r][c] = 0
            stack, size = [(r, c)], 0
            while stack:
                i, j = stack.pop()
                size += 1
                for ni, nj in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                    if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1:
                        grid[ni][nj] = 0
                        stack.append((ni, nj))
            best = max(best, size)
    return best

def clone_graph(node):
    clones = {}                        # original → clone: memo and visited set

    def dfs(cur):
        if cur in clones:
            return clones[cur]
        copy = Node(cur.val)
        clones[cur] = copy             # register before recursing (cycles)
        copy.neighbors = [dfs(nb) for nb in cur.neighbors]
        return copy

    return dfs(node) if node else None

def solve(board):
    m, n = len(board), len(board[0])
    stack = [(r, c) for r in range(m) for c in (0, n - 1)]
    stack += [(r, c) for r in (0, m - 1) for c in range(n)]
    while stack:                       # mark every 'O' reachable from the border
        r, c = stack.pop()
        if 0 <= r < m and 0 <= c < n and board[r][c] == 'O':
            board[r][c] = 'S'
            stack.extend(((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)))
    for r in range(m):
        for c in range(n):
            board[r][c] = 'O' if board[r][c] == 'S' else 'X'

