    return acc

def hamming_weight(n):
    count = 0
    while n:
        n &= n - 1                     # clears the lowest set bit
        count += 1
    return count

def count_bits(n):
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i >> 1] + (i & 1)   # i = (i // 2) with one more low bit
    return dp

def reverse_bits(n):
    res = 0
    for _ in range(32):
        res = (res << 1) | (n & 1)     # push n's lowest bit onto res
        n >>= 1
    return res

def single_number(nums):
    ones = twos = 0                    # per-bit count mod 3
    for x in nums:
        ones = (ones ^ x) & ~twos
        twos = (twos ^ x) & ~ones
    return ones

def get_sum(a, b):
    MASK = 0xFFFFFFFF                  # Python ints are unbounded: emulate 32 bits
    a, b = a & MASK, b & MASK
    while b:
        a, b = (a ^ b) & MASK, ((a & b) << 1) & MASK   # sum without carry, carry
    return a if a <= 0x7FFFFFFF else ~(a ^ MASK)       # back to a signed int

def subsets_with_dup(nums):
    nums.sort()
    res, path = [], []

    def dfs(start):
        res.append(path[:])
        for j in range(start, len(nums)):
            if j > start and nums[j] == nums[j - 1]:
                continue               # same value already tried at this depth
            path.append(nums[j])
            dfs(j + 1)
            path.pop()

    dfs(0)
    return res

def combination_sum(candidates, target):
    res, path = [], []

    def dfs(i, remaining):
        if remaining == 0:
            res.append(path[:])
            return
        for j in range(i, len(candidates)):
            if candidates[j] <= remaining:
                path.append(candidates[j])
                dfs(j, remaining - candidates[j])   # j, not j+1: reuse allowed
                path.pop()

    dfs(0, target)
    return res

def combination_sum2(candidates, target):
    candidates.sort()
    res, path = [], []

    def dfs(i, remaining):
        if remaining == 0:
            res.append(path[:])
            return
        for j in range(i, len(candidates)):
            if j > i and candidates[j] == candidates[j - 1]:
                continue               # skip sibling duplicates
            if candidates[j] > remaining:
                break                  # sorted: nothing later fits either
            path.append(candidates[j])
            dfs(j + 1, remaining - candidates[j])   # each element used once
            path.pop()

    dfs(0, target)
    return res

def letter_combinations(digits):
    if not digits:
