    dp = [True] + [False] * len(s)     # dp[i]: s[:i] can be segmented
    for i in range(1, len(s) + 1):
        for j in range(max(0, i - longest), i):
            if dp[j] and s[j:i] in words:
                dp[i] = True
                break
    return dp[-1]

def max_profit(prices):
    hold, sold, rest = float('-inf'), 0, 0
    for p in prices:
