        hold, sold, rest = max(hold, rest - p), hold + p, max(rest, sold)
    return max(sold, rest)

def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False
    S = total // 2
    dp = [True] + [False] * S          # dp[s]: some subset sums to s
    for x in nums:
        for s in range(S, x - 1, -1):  # downward: each x used at most once
            dp[s] = dp[s] or dp[s - x]
    return dp[S]

def find_target_sum_ways(nums, target):
    total = sum(nums)
    if abs(target) > total or (total + target) % 2:
        return 0
    P = (total + target) // 2          # sum of the '+' group
    dp = [1] + [0] * P                 # dp[s]: subsets summing to s
    for x in nums:
        for s in range(P, x - 1, -1):
            dp[s] += dp[s - x]
    return dp[P]

def change(amount, coins):
    dp = [1] + [0] * amount            # dp[a]: combinations making a
    for c in coins:                    # coins outside: counts sets, not orders
        for a in range(c, amount + 1):
            dp[a] += dp[a - c]
    return dp[amount]

def longest_common_subsequence(a, b):
    if len(a) < len(b):
        a, b = b, a                    # roll over the shorter string
    prev = [0] * (len(b) + 1)
    for i in range(1, len(a) + 1):
        cur = [0] * (len(b) + 1)
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                cur[j] = prev[j - 1] + 1
            else:
                cur[j] = max(prev[j], cur[j - 1])
        prev = cur
    return prev[-1]

def min_distance(a, b):
    prev = list(range(len(b) + 1))     # "" → b[:j] costs j inserts
    for i in range(1, len(a) + 1):
        cur = [i] + [0] * len(b)
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                cur[j] = prev[j - 1]
            else:                      # replace, delete, insert
                cur[j] = 1 + min(prev[j - 1], prev[j], cur[j - 1])
        prev = cur
    return prev[-1]

def is_interleave(a, b, c):
    m, n = len(a), len(b)
    if m + n != len(c):
        return False
    dp = [False] * (n + 1)             # dp[j] for the current row i
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 and j == 0:
                dp[j] = True
                continue
            k = i + j - 1              # next char of c to match
            from_a = i > 0 and dp[j] and a[i - 1] == c[k]
            from_b = j > 0 and dp[j - 1] and b[j - 1] == c[k]
            dp[j] = from_a or from_b
    return dp[n]

def num_distinct(s, t):
    dp = [1] + [0] * len(t)            # dp[j]: ways to form t[:j]
    for ch in s:
        for j in range(len(t), 0, -1): # downward: use ch once per step
            if t[j - 1] == ch:
                dp[j] += dp[j - 1]
    return dp[-1]

def is_match(s, p):
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]   # dp[i][j]: s[:i] ~ p[:j]
    dp[0][0] = True
    for j in range(2, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]    # "a*" can match empty
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                zero = dp[i][j - 2]
                more = p[j - 2] in (s[i - 1], '.') and dp[i - 1][j]
                dp[i][j] = zero or more
            else:
                dp[i][j] = p[j - 1] in (s[i - 1], '.') and dp[i - 1][j - 1]
    return dp[m][n]

