def length_of_lis(nums):
    tails = []                         # tails[k]: smallest tail of a length-k+1 run
    for x in nums:
        i = bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)            # extends the longest run
        else:
            tails[i] = x               # a smaller tail for length i+1
    return len(tails)

def unique_paths(m, n):
    row = [1] * n                      # first row: one way to each cell
    for _ in range(1, m):
        for j in range(1, n):
            row[j] += row[j - 1]       # from above (old row[j]) + from the left
    return row[-1]

def unique_paths_with_obstacles(grid):
    n = len(grid[0])
    row = [1] + [0] * (n - 1)
    for cells in grid:
        for j in range(n):
            if cells[j] == 1:
                row[j] = 0             # obstacle: no paths through here
            elif j > 0:
                row[j] += row[j - 1]
    return row[-1]

def min_path_sum(grid):
    n = len(grid[0])
    row = [0] + [float('inf')] * (n - 1)
    for cells in grid:
        row[0] += cells[0]
        for j in range(1, n):
            row[j] = cells[j] + min(row[j], row[j - 1])   # from above or left
    return row[-1]

def maximal_square(matrix):
    n = len(matrix[0])
    dp = [0] * (n + 1)                 # dp[j]: side of the square ending here
    best = 0
    for row in matrix:
        diag = 0                       # dp value up-left of the current cell
        for j in range(1, n + 1):
            up = dp[j]
            if row[j - 1] == '1':
                dp[j] = 1 + min(dp[j], dp[j - 1], diag)
                best = max(best, dp[j])
            else:
                dp[j] = 0
            diag = up
    return best * best

from functools import lru_cache

def longest_increasing_path(matrix):
    m, n = len(matrix), len(matrix[0])

    @lru_cache(maxsize=None)
    def dfs(r, c):                     # longest path starting at (r, c)
        best = 1
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < m and 0 <= nc < n and matrix[nr][nc] > matrix[r][c]:
                best = max(best, 1 + dfs(nr, nc))
        return best

    return max(dfs(r, c) for r in range(m) for c in range(n))

def longest_palindrome(s):
    start, length = 0, 0
    for center in range(2 * len(s) - 1):   # n letters + n-1 gaps
        l, r = center // 2, (center + 1) // 2
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        if r - l - 1 > length:
            start, length = l + 1, r - l - 1
    return s[start:start + length]

def count_substrings(s):
    count = 0
    for center in range(2 * len(s) - 1):
        l, r = center // 2, (center + 1) // 2
        while l >= 0 and r < len(s) and s[l] == s[r]:
            count += 1                 # every successful step is a palindrome
            l -= 1
            r += 1
    return count

def max_coins(nums):
    a = [1] + nums + [1]               # padded ends
    n = len(a)
    dp = [[0] * n for _ in range(n)]   # dp[i][j]: best for the open interval (i, j)
    for length in range(2, n):
        for i in range(n - length):
            j = i + length
            for k in range(i + 1, j):  # k is the LAST balloon burst in (i, j)
                dp[i][j] = max(dp[i][j], dp[i][k] + a[i] * a[k] * a[j] + dp[k][j])
    return dp[0][n - 1]

def can_jump(nums):
    far = 0                            # farthest index reachable so far
    for i, x in enumerate(nums):
        if i > far:
            return False
        far = max(far, i + x)
    return True

def partition_labels(s):
    last = {c: i for i, c in enumerate(s)}
    res, start, end = [], 0, 0
    for i, c in enumerate(s):
        end = max(end, last[c])        # partition must reach c's last copy
        if i == end:
            res.append(end - start + 1)
            start = i + 1
    return res

import heapq
from collections import Counter

def is_n_straight_hand(hand, group_size):
    if len(hand) % group_size:
        return False
    count = Counter(hand)
    heap = list(count)                 # distinct card values, smallest first
    heapq.heapify(heap)
    while heap:
        first = heap[0]                # smallest card must start a group
        for card in range(first, first + group_size):
            if count[card] == 0:
                return False
            count[card] -= 1
            if count[card] == 0:
                if card != heap[0]:
                    return False       # a smaller card would be left stranded
                heapq.heappop(heap)
    return True

def candy(ratings):
    n = len(ratings)
    candies = [1] * n
    for i in range(1, n):              # left neighbour rule
        if ratings[i] > ratings[i - 1]:
            candies[i] = candies[i - 1] + 1
    for i in range(n - 2, -1, -1):     # right neighbour rule, keep both
        if ratings[i] > ratings[i + 1]:
            candies[i] = max(candies[i], candies[i + 1] + 1)
    return sum(candies)

def two_sum(nums, target):
    seen = {}                          # value → index
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

def is_anagram(s, t):
    if len(s) != len(t):
        return False
    count = [0] * 26
    for a, b in zip(s, t):
        count[ord(a) - 97] += 1
        count[ord(b) - 97] -= 1
    return all(c == 0 for c in count)

from collections import defaultdict

def group_anagrams(strs):
    groups = defaultdict(list)
    for s in strs:
        count = [0] * 26
        for ch in s:
            count[ord(ch) - 97] += 1
        groups[tuple(count)].append(s) # letter counts are the signature
    return list(groups.values())

def contains_duplicate(nums):
    seen = set()
    for x in nums:
        if x in seen:
            return True
        seen.add(x)
    return False

class Node:
    def __init__(self, key=0, val=0):
        self.key, self.val = key, val
        self.prev = self.next = None


class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.map = {}                  # key → node
        self.head, self.tail = Node(), Node()   # dummies; head.next = most recent
        self.head.next, self.tail.prev = self.tail, self.head

    def _remove(self, node):
        node.prev.next, node.next.prev = node.next, node.prev

    def _add_front(self, node):
        node.prev, node.next = self.head, self.head.next
        self.head.next.prev = node
        self.head.next = node

    def get(self, key):
        if key not in self.map:
            return -1
        node = self.map[key]
        self._remove(node)
        self._add_front(node)
        return node.val

    def put(self, key, value):
        if key in self.map:
            self._remove(self.map[key])
        node = Node(key, value)
        self.map[key] = node
        self._add_front(node)
        if len(self.map) > self.cap:
            lru = self.tail.prev       # least recently used
            self._remove(lru)
            del self.map[lru.key]

import random

class RandomizedSet:
    def __init__(self):
        self.values = []
        self.index = {}                # value → position in values

    def insert(self, val):
        if val in self.index:
            return False
        self.index[val] = len(self.values)
        self.values.append(val)
        return True

    def remove(self, val):
        if val not in self.index:
            return False
        i, last = self.index[val], self.values[-1]
        self.values[i], self.index[last] = last, i   # move last into the hole
        self.values.pop()
        del self.index[val]
        return True

    def getRandom(self):
        return random.choice(self.values)

import heapq
from collections import defaultdict

class Twitter:
    def __init__(self):
        self.time = 0
        self.tweets = defaultdict(list)    # user → [(time, tweetId)], oldest first
        self.following = defaultdict(set)

    def postTweet(self, userId, tweetId):
        self.time += 1
        self.tweets[userId].append((self.time, tweetId))

    def getNewsFeed(self, userId):
        heap = []                          # newest tweet of each followee list
        for user in self.following[userId] | {userId}:
            if self.tweets[user]:
                i = len(self.tweets[user]) - 1
                time, tweet = self.tweets[user][i]
                heap.append((-time, tweet, user, i))
        heapq.heapify(heap)
        feed = []
        while heap and len(feed) < 10:
            _, tweet, user, i = heapq.heappop(heap)
            feed.append(tweet)
            if i > 0:                      # advance that user's list
                time, older = self.tweets[user][i - 1]
                heapq.heappush(heap, (-time, older, user, i - 1))
        return feed

    def follow(self, followerId, followeeId):
        if followerId != followeeId:
            self.following[followerId].add(followeeId)

    def unfollow(self, followerId, followeeId):
        self.following[followerId].discard(followeeId)

def spiral_order(matrix):
    res = []
    top, bottom, left, right = 0, len(matrix) - 1, 0, len(matrix[0]) - 1
    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            res.append(matrix[top][c])
        top += 1
        for r in range(top, bottom + 1):
            res.append(matrix[r][right])
        right -= 1
        if top <= bottom:              # a row is still left
            for c in range(right, left - 1, -1):
                res.append(matrix[bottom][c])
            bottom -= 1
        if left <= right:              # a column is still left
            for r in range(bottom, top - 1, -1):
                res.append(matrix[r][left])
            left += 1
    return res

def set_zeroes(matrix):
    m, n = len(matrix), len(matrix[0])
    col0 = False                       # row 0 / col 0 cells are the markers
    for i in range(m):
        if matrix[i][0] == 0:
            col0 = True
        for j in range(1, n):
            if matrix[i][j] == 0:
                matrix[i][0] = matrix[0][j] = 0
    for i in range(m - 1, -1, -1):     # bottom-up so row 0 markers survive
        for j in range(n - 1, 0, -1):
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0
        if col0:
            matrix[i][0] = 0

def my_pow(x, n):
    if n < 0:
        x, n = 1 / x, -n
    result = 1.0
    while n:
        if n & 1:                      # this bit of n contributes x^(2^k)
            result *= x
        x *= x
        n >>= 1
    return result

def copy_random_list(head):
    if not head:
        return None
    cur = head                         # 1. interleave: A → A' → B → B'
    while cur:
        cur.next = Node(cur.val, cur.next)
        cur = cur.next.next
    cur = head                         # 2. wire randoms: A'.random = A.random'
    while cur:
        if cur.random:
            cur.next.random = cur.random.next
        cur = cur.next.next
    cur, copy_head = head, head.next   # 3. split the two lists apart
    while cur:
        copy = cur.next
        cur.next = copy.next
        copy.next = copy.next.next if copy.next else None
        cur = cur.next
    return copy_head
